//! Payload types for browser egress host callbacks.

use serde::{Deserialize, Serialize};

/// Destination parsed from the browser's actual HTTP proxy request.
#[derive(Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct BrowserEgressTarget {
    /// Immutable host-provided policy identifier.
    pub policy_id: String,
    /// Expected `TinySecurity` generation captured at browser session creation.
    pub expected_generation: u64,
    /// Unpredictable browser-proxy session ID generated by `TinyComputer`.
    pub session_id: String,
    /// Canonical `http` or `https` scheme (WS maps to the corresponding HTTP scheme).
    pub scheme: String,
    /// Canonical DNS hostname or IP literal.
    pub hostname: String,
    /// Effective destination port.
    pub port: u16,
}

impl std::fmt::Debug for BrowserEgressTarget {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str("BrowserEgressTarget([REDACTED])")
    }
}

/// Opaque `TinySecurity` grant and its vetted socket addresses.
#[derive(Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct BrowserEgressGrant {
    /// Active generation; mismatch causes refusal before a socket is opened.
    pub generation: u64,
    /// Opaque serialized `TinySecurity` authorization; the module treats it as data.
    pub authorization: String,
    /// Exact vetted socket addresses; the module does not resolve hostnames.
    pub addresses: Vec<String>,
}

impl std::fmt::Debug for BrowserEgressGrant {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str("BrowserEgressGrant([REDACTED])")
    }
}

/// Exact socket selected from the returned grant.
#[derive(Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct BrowserEgressConsumeRequest {
    /// Destination used for authorization.
    pub target: BrowserEgressTarget,
    /// Opaque, unmodified `TinySecurity` authorization returned by `Authorize`.
    pub authorization: String,
    /// One exact member of `BrowserEgressGrant.addresses`.
    pub address: String,
}

impl std::fmt::Debug for BrowserEgressConsumeRequest {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str("BrowserEgressConsumeRequest([REDACTED])")
    }
}

/// Lease validation request for an already consumed tunnel.
#[derive(Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct BrowserEgressValidateRequest {
    /// Opaque, unmodified `TinySecurity` authorization returned by `Authorize`.
    pub authorization: String,
}

impl std::fmt::Debug for BrowserEgressValidateRequest {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str("BrowserEgressValidateRequest([REDACTED])")
    }
}

/// Result for `Consume` and `Validate`; anything other than `allowed: true`
/// refuses or closes the connection.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct BrowserEgressDecision {
    /// Whether `TinySecurity` accepted the exact request or live lease.
    pub allowed: bool,
}
